1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Edge case: empty policy ---
6	  it("quotes an empty item list at 5 G (processing fee only)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	
15	  // --- Base premiums for main items (newcomer: +10% first insurance, +5 fee) ---
16	  it.todo("quotes a plain sword (base 100 G) at 115 G");
17	  it.todo("quotes a plain amulet (base 60 G) at 71 G");
18	  it.todo("quotes a plain staff (base 80 G) at 93 G");
19	  it.todo("quotes a plain potion (base 40 G) at 49 G");
20	
21	  // --- Components and the block of 3 alike ---
22	  it.todo("quotes 1 rune at base premium 25 G");
23	  it.todo("quotes 2 runes at base premium 50 G");
24	  it.todo("quotes 3 runes at base premium 60 G (block applies)");
25	  it.todo("quotes 4 runes at base premium 100 G (no block — block requires exactly 3)");
26	  it.todo("quotes 7 runes at base premium 175 G");
27	  it.todo("quotes 2 runes + 1 moonstone at base premium 75 G (no block: different types)");
28	  it.todo("quotes 3 runes + 3 moonstones at base premium 120 G (two separate blocks)");
29	
30	  // --- Item-specific modifiers ---
31	  it.todo("adds a 50 % curse surcharge to a cursed sword's base premium (100 G → 150 G)");
32	  it.todo("adds a 30 % surcharge for a sword with exactly enchantment 5 (100 G → 130 G)");
33	  it.todo("adds no high-enchantment surcharge for a sword with enchantment 4");
34	  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5 (100 G → 180 G)");
35	
36	  // --- Modifier scope on multi-item policies ---
37	  it.todo("applies the curse surcharge only to the cursed item: cursed sword + plain amulet → 210 G before further modifiers and fee");
38	
39	  // --- Policy-wide modifiers ---
40	  it.todo("grants the 20 % loyalty discount to a customer with exactly 2 years with MHPCO");
41	  it.todo("grants no loyalty discount to a customer with 1 year with MHPCO");
42	  it.todo("adds the 10 % first insurance surcharge on the policy base premium");
43	  it.todo("grants a 15 % follow-up discount on the second quote of a scenario");
44	  it.todo("grants the 15 % follow-up discount on every quote after the first");
45	
46	  // --- Rounding ---
47	  it.todo("rounds a premium of 197.5 G up to 198 G (in the MHPCO's favor)");
48	  it.todo("rounds a payout of 350.5 G down to 350 G (in the MHPCO's favor)");
49	
50	  // --- Integration examples ---
51	  it.todo("quotes a newcomer's cursed sword (steel, enchantment 3) at 165 G");
52	  it.todo("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) at 160 G");
53	
54	  // --- Claims: standard reimbursement ---
55	  it.todo("pays 400 G for a regular sword (steel, enchantment 3) damaged by 500 G (deductible 100 G)");
56	  it.todo("pays 100 G for a rune (insurance value 250 G) damaged by 200 G");
57	
58	  // --- Claims: special clauses ---
59	  it.todo("pays 400 G for a dragon-material sword with exactly enchantment 8 damaged by 1000 G (50 % clause, then deductible)");
60	  it.todo("pays 400 G for a dragon-material sword with enchantment 9 damaged by 1000 G (50 % rule wins over dragon material)");
61	  it.todo("pays 700 G for a dragon-material sword with enchantment 5 damaged by 800 G (full reimbursement, then deductible)");
62	  it.todo("pays 400 G for a steel sword with enchantment 9 damaged by 1000 G (50 % clause, then deductible)");
63	
64	  // --- Claims: deductible per damage event ---
65	  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G → payout 600 G");
66	
67	  // --- Claims: insurance sum and cap ---
68	  it.todo("reports the remaining cap of a policy after a claim");
69	  it.todo("caps a policy covering a sword and an amulet at 3200 G (insurance sum 1600 G)");
70	  it.todo("caps a policy covering a cursed sword at 2000 G (premium modifiers do not raise the cap)");
71	  it.todo("caps a policy covering a sword and 3 runes at 3500 G (insurance sum 1750 G — the block discount affects the premium only)");
72	  it.todo("exhausts the cap across successive claims: 1500 G → payout 1400 G / cap 600 G, then 1500 G → payout 600 G / cap 0 G");
73	
74	  // --- Multiple items of the same type ---
75	  it.todo("insures two swords at an insurance sum of 2000 G (cap 4000 G)");
76	  it.todo("treats two sword damage entries as separate damages, each with its own deductible");
77	  it.todo("rejects a claim with more damage entries of a type than the policy covers");
78	
79	  // --- Errors ---
80	  it.todo("rejects a quote containing an item with an unknown type (e.g. broomstick)");
81	  it.todo("rejects a claim referencing a damaged item that is not part of the policy");
82	  it.todo("rejects a claim containing a damage entry with a negative amount");
